class Solution:
    def maxDistToClosest(self, seats):
        prev = -1
        best = 0
        for i, seat in enumerate(seats):
            if seat == 1:
                if prev == -1:
                    best = max(best, i)
                else:
                    best = max(best, (i - prev) // 2)
                prev = i
        return max(best, len(seats) - 1 - prev)

