#include <stdio.h>
#include <stdlib.h>

int maxDistToClosest(int* seats, int seatsSize) {
    int prev = -1;
    int best = 0;

    for (int i = 0; i < seatsSize; ++i) {
        if (seats[i] == 1) {
            if (prev == -1) {
                if (i > best) best = i;
            } else {
                int gap = (i - prev) / 2;
                if (gap > best) best = gap;
            }
            prev = i;
        }
    }

    int trailing = seatsSize - 1 - prev;
    if (trailing > best) best = trailing;
    return best;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    int cap = 250000;
    int* seats = (int*)malloc((size_t)cap * sizeof(int));
    if (!seats) return 1;

    int count = 0;
    const char* p = line;
    while (*p) {
        if (*p == '0' || *p == '1') {
            if (count >= cap) { free(seats); return 1; }
            seats[count++] = *p - '0';
        }
        ++p;
    }

    printf("%d\n", maxDistToClosest(seats, count));
    free(seats);
    return 0;
}

