import java.io.*;
import java.util.*;

class Solution {
    public int maxDistToClosest(int[] seats) {
        int prev = -1;
        int best = 0;
        for (int i = 0; i < seats.length; i++) {
            if (seats[i] == 1) {
                if (prev == -1) {
                    best = Math.max(best, i);
                } else {
                    best = Math.max(best, (i - prev) / 2);
                }
                prev = i;
            }
        }
        return Math.max(best, seats.length - 1 - prev);
    }
}

public class Main {
    static int[] parseIntArray(String s) {
        s = s.trim();
        if (!s.startsWith("[") || !s.endsWith("]")) throw new IllegalArgumentException("Invalid array");
        s = s.substring(1, s.length() - 1).trim();
        if (s.isEmpty()) return new int[0];
        String[] parts = s.split(",");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i].trim());
        return a;
    }

    static int[] parseArgs(String line) {
        line = line.trim();
        if (!line.startsWith("[[") || !line.endsWith("]]")) throw new IllegalArgumentException("Invalid input");
        return parseIntArray(line.substring(1, line.length() - 1));
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[] seats = parseArgs(line);
        System.out.println(new Solution().maxDistToClosest(seats));
    }
}

